#!/bin/sh
# Build the checked-in iOS project for an arm64 simulator with the simulator
# entitlement profile generated by Xcode.  In particular, do not post-sign the
# app: iOS simulator keychain access is decided while xcodebuild produces the
# simulated xcent file.
set -eu

SCRIPT_DIR=$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)
ROOT=$(CDPATH= cd -- "$SCRIPT_DIR/.." && pwd)

PROJECT=${IOS_PROJECT:-"$ROOT/src-tauri/gen/apple/image-annotation.xcodeproj"}
SCHEME=${IOS_SCHEME:-image-annotation_iOS}
CONFIGURATION=${CONFIGURATION:-release}
SDK=${IOS_SIMULATOR_SDK:-iphonesimulator}
DESTINATION=${IOS_SIMULATOR_DESTINATION:-"generic/platform=iOS Simulator"}
DERIVED_DATA=${IOS_DERIVED_DATA:-"$ROOT/artifacts/ios-simulator/DerivedData"}
OUTPUT_DIR=${IOS_OUTPUT_DIR:-"$ROOT/artifacts/ios-simulator/app"}
TEAM_ID=${DEVELOPMENT_TEAM:-VKFR723PW9}
BUNDLE_ID=${PRODUCT_BUNDLE_IDENTIFIER:-com.imageannotation.desktop}
REBUILD_RUST=${IMAGE_ANNOTATION_REBUILD_RUST:-1}

if [ ! -d "$PROJECT" ]; then
    echo "iOS Xcode project is missing: $PROJECT" >&2
    echo "Generate src-tauri/gen/apple from the checked-in mobile configuration first." >&2
    exit 1
fi

mkdir -p "$DERIVED_DATA" "$OUTPUT_DIR"

# Keep Rust intermediates bounded when the Xcode build phase invokes Tauri's
# Rust export script.  These defaults may be overridden by a release runner.
export CARGO_INCREMENTAL=${CARGO_INCREMENTAL:-0}
export CARGO_PROFILE_DEV_DEBUG=${CARGO_PROFILE_DEV_DEBUG:-0}
export CARGO_PROFILE_RELEASE_DEBUG=${CARGO_PROFILE_RELEASE_DEBUG:-0}

if [ "$REBUILD_RUST" = "1" ]; then
    # Tauri moves the archive product into this directory and cannot replace
    # a non-empty previous .app. Preserve its generated output before rebuilding.
    GENERATED_SIM_APP="$ROOT/src-tauri/gen/apple/build/arm64-sim/Image Annotation.app"
    if [ -d "$GENERATED_SIM_APP" ]; then
        PREVIOUS_OUTPUT="$DERIVED_DATA/previous-tauri-output-$(date +%Y%m%d-%H%M%S)"
        mkdir -p "$PREVIOUS_OUTPUT"
        mv "$GENERATED_SIM_APP" "$PREVIOUS_OUTPUT/Image Annotation.app"
    fi
    (cd "$ROOT" && npm run -- tauri ios build --target aarch64-sim --config src-tauri/tauri.ios.conf.json --no-sign)
fi

# A standalone xcodebuild has no Tauri CLI options WebSocket.  The normal
# `tauri ios build` above owns that server and refreshes libapp.a; the final
# entitlement packaging pass deliberately reuses those archives.
export IMAGE_ANNOTATION_SKIP_RUST_EXPORT=${IMAGE_ANNOTATION_SKIP_RUST_EXPORT:-1}

xcodebuild \
    -project "$PROJECT" \
    -scheme "$SCHEME" \
    -configuration "$CONFIGURATION" \
    -sdk "$SDK" \
    -destination "$DESTINATION" \
    -derivedDataPath "$DERIVED_DATA" \
    CONFIGURATION_BUILD_DIR="$OUTPUT_DIR" \
    DEVELOPMENT_TEAM="$TEAM_ID" \
    PRODUCT_BUNDLE_IDENTIFIER="$BUNDLE_ID" \
    CODE_SIGN_IDENTITY=- \
    CODE_SIGNING_ALLOWED=YES \
    CODE_SIGNING_REQUIRED=NO \
    AD_HOC_CODE_SIGNING_ALLOWED=YES \
    CODE_SIGN_INJECT_BASE_ENTITLEMENTS=YES \
    ENTITLEMENTS_ALLOWED=YES \
    PROVISIONING_PROFILE_REQUIRED=NO \
    build

APP="$OUTPUT_DIR/Image Annotation.app"
if [ ! -d "$APP" ]; then
    echo "xcodebuild completed without an app at: $APP" >&2
    exit 1
fi

echo "Built simulator app: $APP"
SIMULATED_XCENT=$(find "$DERIVED_DATA" -type f -name '*app-Simulated.xcent' -print -quit)
if [ -n "$SIMULATED_XCENT" ]; then
    echo "Simulator entitlement profile: $SIMULATED_XCENT"
    /usr/bin/plutil -p "$SIMULATED_XCENT"
fi
